package com.vandorlabs.neoforge.canopy;

import com.google.gson.*;
import com.vandorlabs.neoforge.door.NativeDoorTargets;
import java.nio.file.*;
import net.minecraft.core.*;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.ClipContext;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.phys.*;

/** Actual registered mixins, loaded external owner discovery and strict nearest-block picking. */
final class CanopyTargetHostChecks {
    private static final BlockPos ROOT=new BlockPos(8,80,8);private static long checks,rays,boxes;private static int emptyCorners,walls;
    private static void need(boolean value,String text){checks++;if(!value)throw new AssertionError("Canopy world targets "+text);}
    private static Vec3 point(JsonArray p){return new Vec3(Double.longBitsToDouble(p.get(0).getAsLong()),Double.longBitsToDouble(p.get(1).getAsLong()),Double.longBitsToDouble(p.get(2).getAsLong()));}
    private static void hit(JsonElement expected,BlockHitResult actual,String context){need(expected.isJsonNull()?actual==null:actual!=null,"Source hit existence "+context);if(actual!=null){var wanted=expected.getAsJsonObject();need(actual.getLocation().equals(point(wanted.getAsJsonArray("point"))),"Source exact point "+context);need(actual.getDirection().get3DDataValue()==wanted.get("face").getAsInt(),"Source exact face "+context);need(actual.getBlockPos().equals(ROOT),"Source standalone owner position");}}
    static void run(ServerLevel world)throws Exception{
        for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++)world.getChunk(x,z);for(var cell:BlockPos.betweenClosed(ROOT.offset(-20,-20,-20),ROOT.offset(20,20,20)))if(!world.getBlockState(cell).isAir())world.setBlock(cell,Blocks.AIR.defaultBlockState(),18);var viewer=new net.minecraft.world.entity.decoration.ArmorStand(world,0,0,0);int profiles=0;
        try(var reader=Files.newBufferedReader(Path.of(System.getenv("VANDOR_CANOPY_PHYSICS_REFERENCE")))){for(String line;(line=reader.readLine())!=null;){var row=JsonParser.parseString(line).getAsJsonObject();var tag=CanopySettingsChecks.tags(row.getAsJsonObject("settings"));tag.putLong("AnchorOffset",0);tag.putBoolean("CenteredPlacement",row.get("centered").getAsBoolean());tag.putFloat("Progress",row.get("progress").getAsFloat());var owner=CanopyHostChecks.put(world,ROOT,row.get("id").getAsString(),Direction.from3DDataValue(row.get("facing").getAsInt()),tag);owner.onLoad();NativeCanopyLifecycle.prepare(owner);need(owner.available()&&owner.publication().draws(),"installed drawing Source profile="+profiles);var geometry=owner.publication().geometry();need(owner.getBlockState().getCollisionShape(world,ROOT).isEmpty(),"released local physical callback stays empty");
            var wantedBoxes=row.getAsJsonArray("boxes");int at=0;for(var shape:world.getBlockCollisions(null,geometry.bounds())){var box=shape.bounds();need(at<wantedBoxes.size(),"no extra actual world collision");var wanted=wantedBoxes.get(at++).getAsJsonArray();double[] words={box.minX,box.minY,box.minZ,box.maxX,box.maxY,box.maxZ};for(int i=0;i<6;i++)need(Double.doubleToRawLongBits(words[i])==wanted.get(i).getAsLong(),"Source world collision coordinate profile="+profiles+" box="+(at-1)+" axis="+i+" expected="+Double.longBitsToDouble(wanted.get(i).getAsLong())+" actual="+words[i]+" shape="+shape+" geometryFirst="+geometry.boxes().get(0));boxes++;}need(at==wantedBoxes.size(),"actual null-entity world callback emits every Source box profile="+profiles+" actual="+at+" expected="+wantedBoxes.size());need(NativeCanopyTargets.retainedBytes()<=8L*1024*1024,"external shape cache byte bound");
            for(var raw:row.getAsJsonArray("rays")){var ray=raw.getAsJsonObject();var start=point(ray.getAsJsonArray("start"));var end=point(ray.getAsJsonArray("end"));var expected=ray.has("hit")?ray.get("hit"):JsonNull.INSTANCE;var target=NativeCanopyTargets.trace(world,start,end);hit(expected,target==null?null:target.hit(),"profile="+profiles+" ray="+rays);var picked=NativeDoorTargets.pick(world,viewer,start,end);hit(expected,picked==null?null:picked.hit(),"nearest profile="+profiles+" ray="+rays);
                if(expected.isJsonNull()&&start.distanceToSqr(end)>1e-8&&new AABB(ROOT).clip(start,end).isPresent()){var actual=world.clip(new ClipContext(start,end,ClipContext.Block.OUTLINE,ClipContext.Fluid.NONE,net.minecraft.world.phys.shapes.CollisionContext.empty()));need(actual.getType()==HitResult.Type.MISS,"actual DDA traverses empty authored union corner");emptyCorners++;}
                if(!expected.isJsonNull()&&start.distanceToSqr(target.hit().getLocation())>16&&walls<12){var block=BlockPos.containing(start.lerp(target.hit().getLocation(),.25));if(!block.equals(ROOT)&&world.getBlockState(block).isAir()){world.setBlock(block,Blocks.STONE.defaultBlockState(),18);need(NativeDoorTargets.pick(world,viewer,start,end)==null,"nearer real solid block remains authoritative");world.setBlock(block,Blocks.AIR.defaultBlockState(),18);walls++;}}
                rays++;
            }
            owner.removing(true);world.removeBlock(ROOT,false);profiles++;
        }}var intent=new CanopyUsePayload(ROOT,net.minecraft.world.InteractionHand.MAIN_HAND);var buffer=new net.minecraft.network.RegistryFriendlyByteBuf(io.netty.buffer.Unpooled.buffer(),world.registryAccess());try{CanopyUsePayload.CODEC.encode(buffer,intent);need(buffer.readableBytes()==9,"fixed use-intent bytes");need(CanopyUsePayload.CODEC.decode(buffer).equals(intent),"use-intent exact round trip");}finally{buffer.release();}
        for(int length:new int[]{0,8,10,64}){var bad=new net.minecraft.network.RegistryFriendlyByteBuf(io.netty.buffer.Unpooled.buffer(),world.registryAccess());try{bad.writeZero(length);boolean refused=false;try{CanopyUsePayload.CODEC.decode(bad);}catch(IllegalArgumentException expected){refused=true;}need(refused,"bounded malformed use length="+length);}finally{bad.release();}}
        var bad=new net.minecraft.network.RegistryFriendlyByteBuf(io.netty.buffer.Unpooled.buffer(),world.registryAccess());try{bad.writeBlockPos(ROOT);bad.writeByte(2);boolean refused=false;try{CanopyUsePayload.CODEC.decode(bad);}catch(IllegalArgumentException expected){refused=true;}need(refused,"invalid use hand");}finally{bad.release();}
        var actor=new net.neoforged.neoforge.common.util.FakePlayer(world,new com.mojang.authlib.GameProfile(java.util.UUID.fromString("224ba50b-a25d-4670-9490-13eff412f3c6"),"CanopyTarget"));actor.setGameMode(net.minecraft.world.level.GameType.SPECTATOR);need(!CanopyUsePayload.apply(actor,intent),"spectator use denied");actor.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);need(!CanopyUsePayload.apply(actor,intent),"removed owner use denied");need(!java.util.concurrent.CompletableFuture.supplyAsync(()->CanopyUsePayload.apply(actor,intent)).get(),"worker use denied before discovery");
        need(profiles==176&&boxes==1191320&&rays==5104,"independent Source coverage");need(emptyCorners>0&&walls==12,"actual empty-corner/nearer-wall negatives");System.out.println("[vandorlabs][canopy-host] world targets PASS profiles="+profiles+" boxes="+boxes+" rays="+rays+" emptyCorners="+emptyCorners+" nearerWalls="+walls+" checks="+checks);
    }
}
